#!/bin/sh
# Auto-generated by claude-acc — do not edit manually.
# Sets CLAUDE_CONFIG_DIR for $PWD via `claude-acc activate`,
# then exec's the real `claude` binary discovered in PATH.

# CLAUDE_ACC_RUN_DEFAULT marks an explicit `claude-acc run default`: skip
# re-deriving CLAUDE_CONFIG_DIR from $PWD, since an empty CLAUDE_CONFIG_DIR
# here means "run the standard account", not "not yet activated".
if [ -z "$CLAUDE_CONFIG_DIR" ] && [ -z "$CLAUDE_ACC_RUN_DEFAULT" ]; then
    eval "$('__CLAUDE_ACC_BIN__' activate --shell posix 2>/dev/null)"
fi
unset CLAUDE_ACC_RUN_DEFAULT

# A `--resume <id>` naming a session that belongs to a different account gets
# an unknown-session error from claude, with no hint the transcript exists one
# account over. Offer to bring it in first — but only when there is a terminal
# to ask on, and only when --resume is actually present, so the common launch
# pays nothing. claude-acc re-checks the arguments itself; a match here is
# just a cheap filter. Never fatal: whatever happens, claude still starts.
case " $* " in
    *" --resume "*|*" --resume="*|*" -r "*)
        if [ -t 0 ] && [ -t 1 ]; then
            '__CLAUDE_ACC_BIN__' session preflight -- "$@" || true
        fi
        ;;
esac

self="$0"
case "$self" in
    /*) ;;
    *) self="$(pwd)/$self" ;;
esac
self_dir="${self%/*}"

IFS=:
for d in $PATH; do
    [ "$d" = "$self_dir" ] && continue
    candidate="$d/claude"
    if [ -x "$candidate" ] && [ "$candidate" != "$self" ]; then
        unset IFS
        exec "$candidate" "$@"
    fi
done
unset IFS

echo "claude-acc: real 'claude' binary not found in PATH" >&2
exit 127
